-- Gỡ V616: workflow engine 321 về bản trước (bỏ node enable_anonymous / if_anonymous_ready và biến groupPostAnonymous), xoá block
-- "[engine] fb_enable_group_anonymous_post" và 2 element đăng ẩn danh; mã FB51 và chính sách chỉ bị tắt (dòng lịch sử cũ có thể đã ghi mã). Chỉ chạy khi workflow
-- và block đang đúng bản V616 (đã ai sửa sau V616 thì dừng, không ghi đè). Gỡ rồi thì chiến dịch bật "Đăng bài ẩn danh" đăng bằng tên thật:
-- tắt ô chọn ở các chiến dịch đó trước. SINH TỪ scripts/build-v616-sql.cjs.
BEGIN;
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '60s';

DO $pre$
DECLARE v_block bigint;
BEGIN
  SELECT id INTO v_block FROM public.auto_blocks WHERE name = '[engine] fb_enable_group_anonymous_post' AND md5(code) = '0687856f3663282482914025fc606aa0';
  IF v_block IS NULL THEN RAISE EXCEPTION 'Gỡ V616: không thấy block "[engine] fb_enable_group_anonymous_post" đúng bản V616, không ghi đè'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.auto_workflows w WHERE w.id = 321
                    AND jsonb_array_length(w.nodes) = 58 AND jsonb_array_length(w.edges) = 72
