h", "itemsExpr": "vars.commentIterations"}, "blockId": 2839, "position": {"x": 0, "y": 1100}, "blockName": "loop", "systemType": "loop"}, {"id": "comment", "label": "Comment iteration", "config": {}, "blockId": 2851, "position": {"x": 0, "y": 1200}, "blockName": "fb_comment_at_position"}, {"id": "merge_comment", "config": {"mode": "any"}, "blockId": 2840, "position": {"x": 100, "y": 1300}, "blockName": "merge", "systemType": "merge"}, {"id": "if_leave", "config": {"condition": "vars.groupPostSubmitted === true && vars.leaveGroupOnPendingApproval === true && vars.groupPostIsPending === true"}, "blockId": 2838, "position": {"x": 100, "y": 1400}, "blockName": "if_else", "systemType": "ifElse"}, {"id": "leave_group", "config": {"enabled": true}, "blockId": 2849, "position": {"x": 0, "y": 1500}, "blockName": "fb_leave_group_if_pending"}, {"id": "merge_leave", "config": {"mode": "any"}, "blockId": 2840, "position": {"x": 100, "y": 1600}, "blockName": "merge", "systemType": "merge"}, {"id": "if_join", "config": {"condition": "vars.groupPostSubmitted === true && vars.autoJoinGroupAfterPost === true && vars.groupPostIsPending !== true"}, "blockId": 2838, "position": {"x": 100, "y": 1700}, "blockName": "if_else", "systemType": "ifElse"}, {"id": "join_group", "config": {"enabled": true}, "blockId": 2850, "position": {"x": 0, "y": 1800}, "blockName": "fb_join_group_if_not_member"}, {"id": "merge_join", "config": {"mode": "any"}, "blockId": 2840, "position": {"x": 100, "y": 1900}, "blockName": "merge", "systemType": "merge"}, {"id": "dismiss_after_nav", "label": "Click popup group nếu có", "config": {}, "blockId": 2872, "position": {"x": 100, "y": 50}, "blockName": "fb_click_group_post_prompt_if_present"}, {"id": "verify_submit", "label": "Xác nhận form đăng bài đã đóng", "config": {"screenshotCaptureOn": "failure", "screenshotCaptureTiming": "after"}, "blockId": 2871, "position": {"x": 100, "y": 760}, "blockName": "fb_verify_group_post_form_closed"}, {"id": "dismiss_after_submi