position": {"x": -260, "y": -460}, "blockName": "merge", "systemType": "merge"}, {"id": "page_identity_capture_result", "label": "Giữ kết quả hành động", "config": {"pageIdentityStateOperation": "capture_result"}, "blockId": 2915, "position": {"x": -260, "y": 2160}, "blockName": "fb_campaign_page_identity_state"}, {"id": "page_identity_restore_join", "label": "Kết thúc phần hành động", "config": {"mode": "any"}, "blockId": 2840, "position": {"x": 140, "y": 2290}, "blockName": "merge", "systemType": "merge"}, {"id": "page_identity_needs_restore", "label": "Cần chuyển về danh tính ban đầu?", "config": {"condition": "vars.runAsPage === true && !!vars.originalIdentityName && (vars.pageIdentityRestoreOnly === true || vars.pageIdentityRestoreAfterTarget !== false)"}, "blockId": 2838, "position": {"x": 140, "y": 2420}, "blockName": "if_else", "systemType": "ifElse"}, {"id": "page_identity_restore", "label": "Chuyển về danh tính ban đầu", "config": {"useOriginalIdentity": true}, "blockId": 2880, "position": {"x": -80, "y": 2550}, "blockName": "fb_switch_identity_by_name"}, {"id": "page_identity_restored", "label": "Kiểm tra đã chuyển về", "config": {"pageIdentityStateOperation": "restored"}, "blockId": 2915, "position": {"x": -80, "y": 2680}, "blockName": "fb_campaign_page_identity_state"}, {"id": "page_identity_result_join", "label": "Kết thúc phiên Page", "config": {"mode": "any"}, "blockId": 2840, "position": {"x": 140, "y": 2810}, "blockName": "merge", "systemType": "merge"}, {"id": "page_identity_result", "label": "Trả kết quả hành động", "config": {"pageIdentityStateOperation": "result"}, "blockId": 2915, "position": {"x": 140, "y": 2940}, "blockName": "fb_campaign_page_identity_state"}, {"id": "if_composer_opened", "config": {"condition": "input.opened === true"}, "blockId": 2838, "position": {"x": 320, "y": 260}, "blockName": "if_else", "systemType": "ifElse"}, {"id": "if_native_group_share", "label": "Chia sẻ bài viết nguồn vào nhóm?", "config": {"condition": "vars