UPDATE public.auto_error SET is_active = false, updated_at = now() WHERE error_code = 'err_fb_group_anonymous_post_not_allowed';

DO $post$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.auto_workflows w WHERE w.id = 321 AND md5(w.nodes::text || w.edges::text) = 'd5172b8a15c0b6f8a973a704dd475f5b'
